            for q in range(p*p, M+1, p):
                if spf[q]==q:
                    spf[q]=p

    phi=list(range(M+1))
    for p in range(2, M+1):
        if phi[p]==p:
            for q in range(p, M+1, p):
                phi[q]-=phi[q]//p

    mod=998244353
    sums=[0]*(M+1)
    cache={}
    ans=0
    weight=1
    out=[]

    for x in a:
        ds=cache.get(x)
