                e=0
                while y%p==0:
                    y//=p
                    e+=1
                fac.append((p,e))
            ds=[1]
            for p,e in fac:
                old=ds[:]
                mul=1
                for _ in range(e):
                    mul*=p
                    ds.extend(d*mul for d in old)
            cache[x]=ds

        c=0
        for d in ds:
