from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        first_a = second_a = 0
        first_id = -1
        gain = [0] * m
        total = 0

        for r in range(1, n + 1):
            for a, idx in buckets[r]:
                if a >= first_a:
                    second_a = first_a
                    first_a, first_id = a, idx
                elif a > second_a:
                    second_a = a

            total += r - first_a
            if first_id != -1:
                gain[first_id] += first_a - second_a

        return total + max(gain)

