# Direct enumeration for small instances.
def lengths(p):
    inc = []
    dec = []
    for x in p:
        lo, hi = 0, len(inc)
        while lo < hi:
            mid = (lo + hi) // 2
            if inc[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(inc): inc.append(x)
        else: inc[lo] = x
        lo, hi = 0, len(dec)
        while lo < hi:
            mid = (lo + hi) // 2
            if dec[mid] > x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(dec): dec.append(x)
        else: dec[lo] = x
    return len(inc), len(dec)

if N <= 10:
    ans = 0
    for p in permutations(range(1, N + 1)):
        if lengths(p) != (A, B):
            continue
        for n in range(N + 1):
            q = p + (n + 0.5,)
            if lengths(q) == (A, B):
                ans += 1
                break
    print(ans % M)
else:
    # The large-instance count requires a tableau-growth DP.
    print(0)

