import sys, math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    machines = []
    idx = 2
    for _ in range(n):
        a, p, b, q = data[idx:idx + 4]
        idx += 4
        machines.append((a, p, b, q))

    def minimum_cost(k, item):
        if k == 0:
            return 0
        a, p, b, q = item
        period = a // math.gcd(a, b)
        max_y = (k - 1) // b  # range where at least one S machine is needed
        best = ((k + b - 1) // b) * q  # use only T machines

        # For each residue modulo period, the cost is linear as y increases
        # by period, so its minimum is at one of the two endpoints.
        for r in range(min(period, max_y + 1)):
            last = r + ((max_y - r) // period) * period
            for y in (r, last):
                x = (k - b * y + a - 1) // a
                cost = x * p + y * q
                if cost < best:
                    best = cost
        return best

    def feasible(k):
        total = 0
        for item in machines:
            total += minimum_cost(k, item)
            if total > budget:
                return False
        return True

    max_rate = max(max(a, b) for a, _, b, _ in machines)
    min_price = min(min(p, q) for _, p, _, q in machines)
    low = 0
    high = budget * max_rate // min_price + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

