class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # steps[x] = number of popcount operations needed to reach 1.
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = 1 + steps[x.bit_count()]

        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for j in range(1, n + 1):
                    if steps[j] <= k - 1 and 0 <= j - ones <= rem:
                        ans += comb[rem][j - ones]
                ones += 1
        return ans % MOD

