import sys
from collections import deque

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    it=iter(data)
    N=next(it); M=next(it); Q=next(it)
    people=[]
    for _ in range(M):
        s=next(it)-1; t=next(it)-1
        people.append((s,t))
    queries=[(next(it)-1,next(it)-1) for _ in range(Q)]
    out=[]
    for L,R in queries:
        par=list(range(N)); sz=[1]*N
        def find(x):
            while par[x]!=x:
                par[x]=par[par[x]]; x=par[x]
            return x
        for i in range(L,R+1):
            s,t=people[i]
            a=find(s); b=find(t)
            if a!=b:
                if sz[a]<sz[b]: a,b=b,a
                par[b]=a; sz[a]+=sz[b]
        # Strict inequalities form a directed graph; a->b means x[a] < x[b].
        adj=[[] for _ in range(N)]; indeg=[0]*N
        possible=True
        for i in range(L,R+1):
            s,t=people[i]
            a=min(s,t); b=max(s,t)
            root=find(s)
            if s<t:
                # All interior potentials exceed the endpoint potential.
                for v in range(a+1,b):
                    z=find(v)
                    if z==root:
                        possible=False; break
                    adj[root].append(z); indeg[z]+=1
            else:
                # Reverse travel: all interior potentials are below the endpoint.
                for v in range(a+1,b):
                    z=find(v)
                    if z==root:
                        possible=False; break
                    adj[z].append(root); indeg[root]+=1
            if not possible: break
        if possible:
            q=deque(i for i in range(N) if find(i)==i and indeg[i]==0)
            visited=0
            while q:
                u=q.popleft(); visited+=1
                for v in adj[u]:
                    indeg[v]-=1
                    if indeg[v]==0: q.append(v)
            possible=(visited==sum(1 for i in range(N) if find(i)==i))
        out.append('Yes' if possible else 'No')
    sys.stdout.write('\n'.join(out))

if __name__=='__main__': solve()

